const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const saved=JSON.parse(localStorage.getItem('riftbound-save')||'{}');let lang=saved.lang||'en',lp=saved.lp??68,wins=saved.wins??8,matches=saved.matches??14,honor=saved.honor??240,streak=saved.streak??3,guildWins=saved.guildWins??2,friends=saved.friends||[{name:'Moonlit',initial:'M',status:'online',guild:true},{name:'AshenFox',initial:'A',status:'online',guild:true},{name:'Lumi',initial:'L',status:'away',guild:true},{name:'Jax',initial:'J',status:'offline',guild:true}];let selected=0,game=null,toastTimer;
const t=k=>translations[lang][k]??translations.en[k]??k;function save(){localStorage.setItem('riftbound-save',JSON.stringify({lang,lp,wins,matches,honor,streak,guildWins,friends}))}function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}function pageName(id){return ({home:t('navHome'),play:t('navPlay'),guild:t('navGuild'),rankings:t('navRanks'),learn:t('navLearn')})[id]}
function render(){document.documentElement.lang=lang;$$('[data-i]').forEach(el=>{el.innerHTML=t(el.dataset.i)});$('#langToggle').textContent=lang==='en'?'FR':'EN';$('#crumbPage').textContent=pageName($('.page.active').id);$('#lp').textContent=lp;$('#wins').textContent=wins;$('#matches').textContent=matches;$('#streak').textContent=streak;$('#honor').textContent=honor;$('#winRate').textContent=matches?Math.round(wins/matches*100)+'%':'0%';const pct=lp;$('#rankBar').style.width=pct+'%';$('#sideProgress').style.width=pct+'%';$('#sideLP').textContent=`${lp} / 100 LP`;$('#guildGoalCount').textContent=guildWins;$('#guildGoalBar').style.width=Math.min(100,guildWins/5*100)+'%';renderFriends();renderChampions();renderGuild();renderLeaderboard();renderLessons();renderParty();renderActivity();if(game)updateBattle()}
function renderFriends(){const fr=friends.map((f,i)=>`<div class="friend"><div class="avatar">${f.initial}</div><div class="friend-info"><b>${escapeHTML(f.name)}</b><small>${t(f.status==='online'?'playing':f.status==='away'?'idle':'online')}</small></div><span class="dot ${f.status==='away'?'away':f.status==='offline'?'off':''}"></span><button class="friend-action" aria-label="${t('challenge')}" data-challenge="${i}">···</button></div>`).join('');$('#friendList').innerHTML=fr;$$('[data-challenge]').forEach(b=>b.onclick=()=>openFriendModal(+b.dataset.challenge))}
function renderChampions(){const champs=t('champs');$('#champions').innerHTML=champs.map((c,i)=>`<button class="champion ${selected===i?'selected':''}" data-champ="${i}"><div class="champ-icon">${c[2]}</div><b>${c[0]}</b><small>${c[1]}</small></button>`).join('');$$('[data-champ]').forEach(b=>b.onclick=()=>{if(game?.active){toast(t('alreadyPlaying'));return}selected=+b.dataset.champ;renderChampions();$('#heroName').textContent=t('champs')[selected][0];$('#heroIcon').textContent=t('champs')[selected][2]})}
function renderGuild(){const names=[['You','Y','Guild leader'],...friends.filter(f=>f.guild).map(f=>[f.name,f.initial,'Member'])];$('#guildMembers').innerHTML=names.map((m,i)=>`<div class="member-row"><div class="avatar">${m[1]}</div><div><b>${escapeHTML(m[0])}</b><small>${i===0?(lang==='fr'?'Or II · En ligne':'Gold II · Online'):t(friends.find(f=>f.name===m[0])?.status==='online'?'playing':'idle')}</small></div><span class="role">${i===0?(lang==='fr'?'Chef':'Leader'):(lang==='fr'?'Membre':'Member')}</span></div>`).join('')}
function renderLeaderboard(){const entries=[{name:'Starfall',guild:'Aurora',tier:'Gold I',lp:96,rate:'71%'},{name:'you',guild:'Golden Owls',tier:`Gold ${lp>=100?'I':'II'}`,lp,rate:matches?Math.round(wins/matches*100)+'%':'0%',you:true},{name:'Moonlit',guild:'Golden Owls',tier:'Gold II',lp:61,rate:'60%'},{name:'VelvetHex',guild:'Nightbloom',tier:'Gold III',lp:49,rate:'54%'},{name:'AshenFox',guild:'Golden Owls',tier:'Silver I',lp:88,rate:'51%'}].sort((a,b)=>b.lp-a.lp);$('#leaderboard').innerHTML=entries.map((r,i)=>`<tr class="${r.you?'you':''}"><td>${String(i+1).padStart(2,'0')}</td><td><b>${r.name}</b>${r.you?' <small>('+ (lang==='fr'?'toi':'you')+')</small>':''}</td><td>${r.guild}</td><td class="rank-chip">◈ ${r.tier}</td><td>${r.lp}</td><td>${r.rate}</td></tr>`).join('');const tiers=[['Silver','#9eacbd','◈'],['Gold','#e4b75e','✦'],['Platinum','#74d0c0','⬡']];$('#tierCards').innerHTML=tiers.map((x,i)=>`<div class="stat" style="border-color:${i===1?'#55482f':'var(--line)'}"><small>${lang==='fr'?'PALIER':'TIER'} ${i+1}</small><b style="color:${x[1]}">${x[2]} ${x[0]}</b><small>${['0–999 LP','1,000–1,999 LP','2,000+ LP'][i]}</small></div>`).join('')}
function renderLessons(){$('#lessonCards').innerHTML=t('lessons').map((l,i)=>`<div class="lesson"><div class="lesson-icon">${l[2]}</div><div><h3>${i+1}. ${l[0]}</h3><p>${l[1]}</p></div></div>`).join('')}
function renderParty(){const online=friends.filter(f=>f.status==='online');$('#partyFriends').innerHTML=online.length?online.slice(0,3).map(f=>`<div class="friend"><div class="avatar">${f.initial}</div><div class="friend-info"><b>${escapeHTML(f.name)}</b><small>${t('online')}</small></div><button class="button ghost small" data-party="${escapeHTML(f.name)}">${t('invite')}</button></div>`).join(''):`<p class="subtitle">${lang==='fr'?'Aucun ami en ligne pour le moment.':'No friends online right now.'}</p>`;$$('[data-party]').forEach(b=>b.onclick=()=>toast(t('inviteParty').replace('{name}',b.dataset.party)))}
function renderActivity(){const list=[{icon:'⚔',text:`<b>Moonlit</b> ${lang==='fr'?'a remporté une partie classée':'won a ranked match'}`,time:lang==='fr'?'il y a 12 min':'12 min ago',color:'green'},{icon:'✦',text:`<b>${lang==='fr'?'Ta guilde':'Your guild'}</b> ${lang==='fr'?'a gagné 240 honneur':'earned 240 honor'}`,time:lang==='fr'?'il y a 1 h':'1 hr ago',color:''},{icon:'♜',text:`<b>AshenFox</b> ${lang==='fr'?'a rejoint Golden Owls':'joined Golden Owls'}`,time:lang==='fr'?'hier':'yesterday',color:''}];$('#activityList').innerHTML=list.map(a=>`<div class="activity-item"><div class="activity-icon">${a.icon}</div><div>${a.text}<small>${a.time}</small></div></div>`).join('')}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function changePage(id){$$('.page').forEach(p=>p.classList.toggle('active',p.id===id));$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$('#crumbPage').textContent=pageName(id);if(id==='play'&&game)updateBattle();window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav button').forEach(b=>b.onclick=()=>changePage(b.dataset.page));$$('[data-goto]').forEach(b=>b.onclick=()=>changePage(b.dataset.goto));$('#langToggle').onclick=()=>{lang=lang==='en'?'fr':'en';save();render()};$('#tutorialTop').onclick=()=>showTutorial();$('#startTutorial').onclick=()=>showTutorial();
function showModal(title,body,actions){$('#modalRoot').innerHTML=`<div class="modal-back" id="modalBack"><div class="modal"><div class="modal-head"><h2>${title}</h2><button id="closeModal">×</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`;$('#closeModal').onclick=closeModal;$('#modalBack').onclick=e=>{if(e.target.id==='modalBack')closeModal()}}
function closeModal(){$('#modalRoot').innerHTML=''}function showTutorial(){showModal(t('tutorialTitle'),`<p style="font-size:13px;color:#d9dce1;line-height:1.75">${t('tutorialBody')}</p><div class="tutorial-grid" style="grid-template-columns:1fr 1fr">${t('lessons').map((l,i)=>`<div class="lesson" style="padding:11px"><div class="lesson-icon">${i+1}</div><div><h3>${l[0]}</h3><p>${l[1]}</p></div></div>`).join('')}</div>`,`<button class="button" id="tutorialDone">${t('tutorialClose')}</button>`);$('#tutorialDone').onclick=closeModal}
function openFriendModal(i){const f=friends[i];showModal(escapeHTML(f.name),`<p>${escapeHTML(f.name)} · ${t(f.status==='online'?'playing':f.status==='away'?'idle':'online')}</p>`,`<button class="button secondary" id="friendInvite">${t('invite')}</button><button class="button" id="friendChallenge">${t('challenge')}</button>`);$('#friendInvite').onclick=()=>{toast(t('inviteParty').replace('{name}',f.name));closeModal()};$('#friendChallenge').onclick=()=>{closeModal();changePage('play');toast(t('queued'))}}
$('#addFriend').onclick=()=>{showModal(t('add'),`<p>${t('invitePrompt')}</p><input id="friendName" maxlength="20" placeholder="${lang==='fr'?'Ex. Camille':'e.g. NovaRider'}">`,`<button class="button" id="addFriendConfirm">${t('add')}</button>`);$('#addFriendConfirm').onclick=addFriend;$('#friendName').onkeydown=e=>{if(e.key==='Enter')addFriend()};$('#friendName').focus()};function addFriend(){let name=$('#friendName').value.trim();if(!name){toast(t('typeName'));return}if(friends.some(f=>f.name.toLowerCase()===name.toLowerCase())){closeModal();toast(lang==='fr'?'Cet ami est déjà dans ta liste.':'This friend is already on your list.');return}friends.unshift({name,initial:name[0].toUpperCase(),status:'online',guild:false});save();closeModal();render();toast(t('friendAdded').replace('{name}',name))}
$('#inviteGuild').onclick=()=>{$('#inviteInput').focus();$('#inviteInput').scrollIntoView({behavior:'smooth',block:'center'})};$('#sendInvite').onclick=()=>{const input=$('#inviteInput'),name=input.value.trim();if(!name){toast(t('typeName'));input.focus();return}if(friends.some(f=>f.name.toLowerCase()===name.toLowerCase()))friends.find(f=>f.name.toLowerCase()===name.toLowerCase()).guild=true;else friends.unshift({name,initial:name[0].toUpperCase(),status:'online',guild:true});input.value='';save();render();toast(t('guildInvited').replace('{name}',name))};$('#inviteInput').onkeydown=e=>{if(e.key==='Enter')$('#sendInvite').click()};

const champStats=[{hp:100,damage:18},{hp:120,damage:15},{hp:90,damage:24}];function startGame(){if(game?.active){toast(t('alreadyPlaying'));return}const c=champStats[selected];game={active:true,hp:c.hp,maxHp:c.hp,enemy:100,maxEnemy:100,gold:0,xp:0,level:1,damage:c.damage,potion:true,turn:0,log:t('matchStarted')};$('#matchState').style.display='inline';$('#matchTitle').textContent=lang==='fr'?'Duel classé en cours':'Ranked duel in progress';$('#matchSub').textContent=lang==='fr'?'En or, tout se joue maintenant':'Gold League · Make this one count';$('#startMatch').disabled=true;$('#farm').disabled=false;$('#attack').disabled=false;$('#potion').disabled=false;updateBattle()}
function opponentTurn(dmg){if(!game?.active)return;game.hp=Math.max(0,game.hp-dmg);game.turn++;if(game.hp<=0){finishGame(false);return}updateBattle()}
function actionFarm(){if(!game?.active)return;game.gold+=35;game.xp+=20;let leveled=false;if(game.xp>=game.level*40){game.xp-=game.level*40;game.level++;game.damage+=4;leveled=true}const log=lang==='fr'?`${t('farmLog')}${leveled?` Niveau ${game.level} ! Tes dégâts augmentent.`:''}`:`${t('farmLog')}${leveled?` Level ${game.level}! Your damage increases.`:''}`;game.log=log;opponentTurn(7)}
function actionAttack(){if(!game?.active)return;const dmg=game.damage+Math.floor(Math.random()*5);game.enemy=Math.max(0,game.enemy-dmg);if(game.enemy<=0){game.log=t('winLog');finishGame(true);return}const hit=8+Math.floor(Math.random()*5);game.log=t('tradeLog').replace('{dmg}',dmg).replace('{hit}',hit);opponentTurn(hit)}
function actionHeal(){if(!game?.active||!game.potion)return;game.potion=false;game.hp=Math.min(game.maxHp,game.hp+30);const hit=6+Math.floor(Math.random()*4);game.log=t('healLog').replace('{hit}',hit);opponentTurn(hit);$('#potion').disabled=true}
function finishGame(won){if(!game)return;game.active=false;matches++;if(won){wins++;streak++;lp+=18;honor+=30;guildWins=Math.min(5,guildWins+1);game.log=t('winLog');if(lp>=100){lp-=100;$('#division').textContent='I';setTimeout(()=>toast(t('divisionUp').replace('{division}','I')),450)}}else{streak=0;lp=Math.max(0,lp-12);game.log=t('loseLog')}save();$('#startMatch').disabled=false;$('#startMatch').innerHTML=`<span>${lang==='fr'?'Rejouer':'Play again'}</span><span>${t('matchHint')}</span>`;$('#farm').disabled=true;$('#attack').disabled=true;$('#potion').disabled=true;$('#matchState').style.display='none';$('#matchTitle').textContent=won?(lang==='fr'?'Victoire !':'Victory!'):(lang==='fr'?'Défaite':'Defeat');$('#matchSub').textContent=won?(lang==='fr'?'+18 LP · Beau duel':' +18 LP · Well played'):(lang==='fr'?'−12 LP · La prochaine sera la bonne':'−12 LP · Next one is yours');render();$('#battleLog').textContent=game.log}
function updateBattle(){if(!game)return;$('#heroName').textContent=t('champs')[selected][0];$('#heroIcon').textContent=t('champs')[selected][2];$('#heroHealth').style.width=Math.max(0,game.hp/game.maxHp*100)+'%';$('#heroHpText').textContent=`${game.hp} / ${game.maxHp} HP`;$('#enemyHealth').style.width=Math.max(0,game.enemy/game.maxEnemy*100)+'%';$('#enemyHpText').textContent=`${game.enemy} / ${game.maxEnemy} HP`;$('#gold').textContent=game.gold;$('#xp').textContent=game.xp;$('#level').textContent=game.level;$('#battleLog').textContent=game.log;$('#potion').disabled=!game.active||!game.potion;$('#farm').disabled=!game.active;$('#attack').disabled=!game.active}
$('#startMatch').onclick=startGame;$('#farm').onclick=actionFarm;$('#attack').onclick=actionAttack;$('#potion').onclick=actionHeal;$$('.page').forEach(p=>p.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()}));render();
</script></body></html>

